{"file_path":"src/cli.js","content":"#!/usr/bin/env node

import { readFileSync } from 'fs';

// Read all input from stdin
let input = '';
try {
  input = readFileSync(0, 'utf8');
} catch {
  process.stderr.write('error: failed to read input\n');
  process.exit(2);
}

// Parse arguments
const args = process.argv.slice(2);
if (args.length !== 1 || !['rounds', 'tally'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js rounds|tally\n');
  process.exit(2);
}
const mode = args[0];

// Parse input
const lines = input.split('\n');
// Drop empty tail from trailing newline
if (lines.length > 0 && lines[lines.length - 1] === '') {
  lines.pop();
}

let candidates = null;
const ballots = [];

// Process each line
for (let rawLineNum = 0; rawLineNum < lines.length; rawLineNum++) {
  let line = lines[rawLineNum];
  const lineNum = rawLineNum + 1;

  // Trim
  line = line.trim();

  // Skip empty lines and comments
  if (line === '' || line.startsWith('#')) {
    continue;
  }

  // Split on whitespace
  const parts = line.split(/\s+/);
  const directive = parts[0];

  if (directive === 'candidates') {
    if (candidates !== null || ballots.length > 0) {
      process.stderr.write(`error: line ${lineNum}: candidates must be declared once, before any ballot\n`);
      process.exit(2);
    }
    if (parts.length < 2) {
      process.stderr.write(`error: line ${lineNum}: expected candidates <name>...\n`);
      process.exit(2);
    }

    const names = parts.slice(1);
    const seen = new Set();
    candidates = [];
    for (const name of names) {
      if (!/^[a-zA-Z0-9_-]+$/.test(name)) {
        process.stderr.write(`error: line ${lineNum}: invalid candidate name ${name}\n`);
        process.exit(2);
      }
      if (seen.has(name)) {
        process.stderr.write(`error: line ${lineNum}: candidate ${name} is declared twice\n`);
        process.exit(2);
      }
      seen.add(name);
      candidates.push(name);
    }
  } else if (directive === 'ballot') {
    if (candidates === null) {
      process.stderr.write(`error: line ${lineNum}: candidates must be declared once, before any ballot\n`);
      process.exit(2);
    }

    if (parts.length < 3) {
      process.stderr.write(`error: line ${lineNum}: expected ballot <count> <candidate>...\n`);
      process.exit(2);
    }

    const countStr = parts[1];
    const count = parseInt(countStr, 10);
    if (countStr !== count.toString() || count <= 0) {
      process.stderr.write(`error: line ${lineNum}: count must be a positive integer\n`);
      process.exit(2);
    }

    const ranking = parts.slice(2);

    const candidateSet = new Set(candidates);
    const seen = new Set();
    for (const name of ranking) {
      if (!candidateSet.has(name)) {
        process.stderr.write(`error: line ${lineNum}: unknown candidate ${name}\n`);
        process.exit(2);
      }
      if (seen.has(name)) {
        process.stderr.write(`error: line ${lineNum}: candidate ${name} is repeated\n`);
        process.exit(2);
      }
      seen.add(name);
    }

    ballots.push({ count, ranking });
  } else {
    process.stderr.write(`error: line ${lineNum}: unknown directive ${directive}\n`);
    process.exit(2);
  }
}

if (candidates === null) {
  process.stderr.write('error: no candidates\n');
  process.exit(2);
}

// Helper function to apply tiebreaker across rounds
function tiebreak(tied, roundVotesHistory) {
  if (tied.length === 1) return tied[0];

  for (let r = 0; r < roundVotesHistory.length; r++) {
    const votes = tied.map(c => roundVotesHistory[r].votes[c] || 0);
    const minVotes = Math.min(...votes);
    const maxVotes = Math.max(...votes);

    if (minVotes !== maxVotes) {
      // They differ in this round
      const survivors = tied.filter(c => (roundVotesHistory[r].votes[c] || 0) === minVotes);
      return tiebreak(survivors, roundVotesHistory);
    }
  }

  // All rounds have equal votes, eliminate the one whose name sorts last
  tied.sort((a, b) => b.localeCompare(a));
  return tied[0];
}

// Run the election
const rounds = [];
let continuing = new Set(candidates);

// Track where each ballot is in the ranking
const ballotStates = ballots.map(b => ({
  count: b.count,
  ranking: b.ranking,
  nextIndex: 0
}));

while (true) {
  // Count votes
  const votes = {};
  for (const c of candidates) {
    votes[c] = 0;
  }
  let exhausted = 0;

  for (const state of ballotStates) {
    let found = false;
    while (state.nextIndex < state.ranking.length) {
      const c = state.ranking[state.nextIndex];
      state.nextIndex++;
      if (continuing.has(c)) {
        votes[c] += state.count;
        found = true;
        break;
      }
    }
    if (!found) {
      exhausted += state.count;
    }
  }

  // Record this round (only continuing candidates)
  const roundVotes = {};
  for (const c of continuing) {
    roundVotes[c] = votes[c];
  }
  rounds.push({ votes: roundVotes, exhausted });

  // Calculate active total (ballots that counted)
  const activeTotal = Object.values(roundVotes).reduce((a, b) => a + b, 0);

  // Check for winner
  let winner = null;
  if (activeTotal > 0) {
    for (const c of continuing) {
      if (votes[c] * 2 > activeTotal) {
        winner = c;
        break;
      }
    }
  }

  if (winner !== null || activeTotal === 0) {
    break;
  }

  // Find candidate to eliminate
  const continuingList = Array.from(continuing);

  // Find minimum vote count
  let minVotes = Math.min(...continuingList.map(c => votes[c]));
  let tied = continuingList.filter(c => votes[c] === minVotes);

  // Apply tiebreaker
  const eliminated = tiebreak(tied, rounds);
  rounds[rounds.length - 1].eliminated = eliminated;
  continuing.delete(eliminated);
}

// Output
if (mode === 'rounds') {
  for (let i = 0; i < rounds.length; i++) {
    const r = rounds[i];

    // Candidates in this round are those in roundVotes
    const cands = Object.keys(r.votes);
    cands.sort((a, b) => {
      if (r.votes[b] !== r.votes[a]) {
        return r.votes[b] - r.votes[a];
      }
      return a.localeCompare(b);
    });

    const entries = cands.map(c => `${c}=${r.votes[c]}`);
    process.stdout.write(`round ${i + 1}: ${entries.join(' ')} exhausted=${r.exhausted}\n`);

    if (r.eliminated) {
      process.stdout.write(`eliminated ${r.eliminated}\n`);
    }
  }
} else {
  process.stdout.write(`rounds ${rounds.length}\n`);
}

// Output winner
let winner = null;
if (rounds.length > 0) {
  const lastRound = rounds[rounds.length - 1];
  const activeTotal = Object.values(lastRound.votes).reduce((a, b) => a + b, 0);

  for (const c of Object.keys(lastRound.votes)) {
    if (lastRound.votes[c] * 2 > activeTotal) {
      winner = c;
      break;
    }
  }
}

if (winner) {
  process.stdout.write(`winner ${winner}\n`);
} else {
  process.stdout.write('no winner\n');
}
"}

