{"file_path":"src/resolver.js","content":"/**
 * Resolve a reference against a base by RFC 3986 section 5.2.2, strict form:
 * a reference that repeats the base's scheme is still an absolute URI.
 */

export function resolveURI(base, ref) {
  const target = {
    scheme: null,
    authority: null,
    path: '',
    query: null,
    fragment: null,
    userinfo: null,
    host: null,
    port: null
  }

  if (ref.scheme !== null) {
    target.scheme = ref.scheme
    copyAuthority(target, ref)
    target.path = ref.path
    target.query = ref.query
  } else {
    target.scheme = base.scheme
    if (ref.authority !== null) {
      copyAuthority(target, ref)
      target.path = ref.path
      target.query = ref.query
    } else {
      copyAuthority(target, base)
      if (ref.path === '') {
        target.path = base.path
        target.query = ref.query !== null ? ref.query : base.query
      } else {
        target.path = ref.path.startsWith('/')
          ? ref.path
          : mergePaths(base, ref.path)
        target.query = ref.query
      }
    }
  }

  target.fragment = ref.fragment
  return target
}

function copyAuthority(target, source) {
  target.authority = source.authority
  target.userinfo = source.userinfo
  target.host = source.host
  target.port = source.port
}

function mergePaths(base, refPath) {
  if (base.authority !== null && base.path === '') return '/' + refPath
  const lastSlash = base.path.lastIndexOf('/')
  if (lastSlash === -1) return refPath
  return base.path.slice(0, lastSlash + 1) + refPath
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Nothing reaches standard output unless
 * every record succeeds.
 */

import { parseURI } from './parser.js'
import { normalizeURI } from './normalizer.js'
import { resolveURI } from './resolver.js'
import { readStdin } from './stdin.js'

function fail(message) {
  const err = new Error(message)
  err.exitCode = 2
  return err
}

function processLine(mode, line, lineNum) {
  if (mode === 'normalize') {
    return normalizeURI(parseURI(line, lineNum))
  }

  const space = line.indexOf(' ')
  if (space === -1) {
    throw fail(`error: line ${lineNum}: expected a base and a reference`)
  }

  const base = parseURI(line.slice(0, space), lineNum)
  if (base.scheme === null) {
    throw fail(`error: line ${lineNum}: the base has no scheme`)
  }

  const ref = parseURI(line.slice(space + 1), lineNum)
  return normalizeURI(resolveURI(base, ref))
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exitCode = 2
    return
  }
  const mode = args[0]

  const input = await readStdin()
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const output = []
  for (let i = 0; i < lines.length; i++) {
    let result
    try {
      result = processLine(mode, lines[i], i + 1)
    } catch (err) {
      if (err.exitCode === 2) {
        process.stderr.write(err.message + '\n')
        process.exitCode = 2
        return
      }
      throw err
    }
    output.push(result)
  }

  if (output.length > 0) process.stdout.write(output.join('\n') + '\n')
}

main().catch(err => {
  process.stderr.write(`error: ${err && err.message ? err.message : err}\n`)
  process.exitCode = 2
})
"}

