{"file_path":"src/parse.js","content":"/**
 * Parsing and validation of the limiter file.
 */

const TOKEN_RE = /^[A-Za-z0-9_./:-]+$/;
const UINT_RE = /^(0|[1-9][0-9]*)$/;

function fail(lineNum, reason) {
  const err = new Error(`error: line ${lineNum}: ${reason}`);
  err.parseError = true;
  return err;
}

function parseUint(text, field, least, lineNum) {
  if (!UINT_RE.test(text)) {
    throw fail(lineNum, `${field} must be an integer of at least ${least}`);
  }
  const value = BigInt(text);
  if (value < BigInt(least)) {
    throw fail(lineNum, `${field} must be an integer of at least ${least}`);
  }
  return value;
}

export function parse(input) {
  let lines = input.split('\n');
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
  }

  const policies = new Map(); // name -> definition
  const routes = []; // { prefix, policyNames }
  const events = []; // { tick, key }
  const seenPrefixes = new Set();
  let sawEvent = false;
  let lastTick = null;

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const line = lines[i].trim();
    if (line === '' || line.startsWith('#')) continue;

    const parts = line.split(/\s+/);
    const directive = parts[0];

    if (directive === 'bucket') {
      if (sawEvent) throw fail(lineNum, 'declarations must come before the first event');
      if (parts.length !== 5) {
        throw fail(lineNum, 'expected bucket <name> <capacity> <refill> <per>');
      }
      const name = parts[1];
      if (!TOKEN_RE.test(name)) throw fail(lineNum, `invalid policy name ${name}`);
      const capacity = parseUint(parts[2], 'capacity', 1, lineNum);
      const refill = parseUint(parts[3], 'refill', 0, lineNum);
      const per = parseUint(parts[4], 'per', 1, lineNum);
      if (policies.has(name)) throw fail(lineNum, `policy ${name} is declared twice`);
      policies.set(name, { type: 'bucket', capacity, refill, per });
    } else if (directive === 'window') {
      if (sawEvent) throw fail(lineNum, 'declarations must come before the first event');
      if (parts.length !== 4) {
        throw fail(lineNum, 'expected window <name> <limit> <span>');
      }
      const name = parts[1];
      if (!TOKEN_RE.test(name)) throw fail(lineNum, `invalid policy name ${name}`);
      const limit = parseUint(parts[2], 'limit', 0, lineNum);
      const span = parseUint(parts[3], 'span', 1, lineNum);
      if (policies.has(name)) throw fail(lineNum, `policy ${name} is declared twice`);
      policies.set(name, { type: 'window', limit, span });
    } else if (directive === 'route') {
      if (sawEvent) throw fail(lineNum, 'declarations must come before the first event');
      if (parts.length < 3) {
        throw fail(lineNum, 'expected route <prefix> <policy>...');
      }
      const prefix = parts[1];
      if (!TOKEN_RE.test(prefix)) throw fail(lineNum, `invalid route prefix ${prefix}`);
      if (seenPrefixes.has(prefix)) throw fail(lineNum, `prefix ${prefix} is routed twice`);
      const policyNames = parts.slice(2);
      for (const policyName of policyNames) {
        if (!policies.has(policyName)) throw fail(lineNum, `unknown policy ${policyName}`);
      }
      seenPrefixes.add(prefix);
      routes.push({ prefix, policyNames });
    } else if (directive === 'event') {
      if (parts.length !== 3) {
        sawEvent = true;
        throw fail(lineNum, 'expected event <tick> <key>');
      }
      const tick = parseUint(parts[1], 'tick', 0, lineNum);
      const key = parts[2];
      if (!TOKEN_RE.test(key)) throw fail(lineNum, `invalid key ${key}`);
      if (lastTick !== null && tick < lastTick) {
        throw fail(lineNum, `tick ${tick} is before tick ${lastTick}`);
      }
      lastTick = tick;
      sawEvent = true;
      events.push({ tick, key });
    } else {
      throw fail(lineNum, `unknown directive ${directive}`);
    }
  }

  return { policies, routes, events };
}
"}

