{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input --
 * mine, the base they both derive from, and theirs, separated by `%%%` lines
 * -- and report their three-way merge.
 */

import { readFileSync, writeSync } from 'fs'
import { buildRegions, renderMerge, renderRegions } from './merge.js'

function fail (message) {
  writeSync(2, `error: ${message}\n`)
  process.exit(2)
}

const mode = process.argv[2]
if (mode !== 'merge' && mode !== 'merge2' && mode !== 'regions') {
  fail('usage: cli.js merge|merge2|regions')
}

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
// Drop the empty tail a trailing newline leaves.
if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

const parts = [[]]
for (const line of lines) {
  if (line === '%%%') parts.push([])
  else parts[parts.length - 1].push(line)
}

if (parts.length !== 3) fail('expected three parts separated by %%%')

const [mine, base, theirs] = parts
const regions = buildRegions(mine, base, theirs)
const { lines: out, conflict } =
  mode === 'regions' ? renderRegions(regions) : renderMerge(regions, mode === 'merge')

if (out.length > 0) writeSync(1, out.join('\n') + '\n')
process.exit(conflict ? 1 : 0)
"}

