{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'

// ============================================================================
// URI Parser
// ============================================================================

class URI {
  constructor(scheme = null, authority = null, path = '', query = null, fragment = null) {
    this.scheme = scheme
    this.authority = authority
    this.path = path
    this.query = query
    this.fragment = fragment
  }

  static parse(uriRef) {
    let scheme = null
    let authority = null
    let path = ''
    let query = null
    let fragment = null

    let str = uriRef
    let i = 0

    // Parse scheme: optional, ends at ':' (but ':' may not be preceded by '/', '?', '#')
    const schemeEndIdx = str.indexOf(':')
    if (schemeEndIdx > 0) {
      const beforeColon = str.substring(0, schemeEndIdx)
      // Check if there's a '/', '?', or '#' before the ':'
      if (!beforeColon.includes('/') && !beforeColon.includes('?') && !beforeColon.includes('#')) {
        scheme = beforeColon
        i = schemeEndIdx + 1
      }
    }

    str = str.substring(i)
    i = 0

    // Parse authority: optional, introduced by '//' and runs to next '/', '?', or '#'
    if (str.startsWith('//')) {
      let authEnd = str.indexOf('/', 2)
      let queryStart = str.indexOf('?', 2)
      let fragmentStart = str.indexOf('#', 2)

      let endIdx = -1
      if (authEnd === -1) endIdx = queryStart
      else if (queryStart === -1) endIdx = authEnd
      else endIdx = Math.min(authEnd, queryStart)

      if (fragmentStart !== -1 && (endIdx === -1 || fragmentStart < endIdx)) {
        endIdx = fragmentStart
      }

      if (endIdx === -1) {
        authority = str.substring(2)
        i = str.length
      } else {
        authority = str.substring(2, endIdx)
        i = endIdx
      }
    }

    str = str.substring(i)
    i = 0

    // Parse path: runs to next '?' or '#'
    let pathEnd = str.indexOf('?')
    let fragmentStart = str.indexOf('#')
    if (pathEnd === -1) pathEnd = fragmentStart
    else if (fragmentStart !== -1 && fragmentStart < pathEnd) pathEnd = fragmentStart

    if (pathEnd === -1) {
      path = str
      i = str.length
    } else {
      path = str.substring(0, pathEnd)
      i = pathEnd
    }

    str = str.substring(i)
    i = 0

    // Parse query: optional, from '?' to next '#'
    if (str.startsWith('?')) {
      fragmentStart = str.indexOf('#', 1)
      if (fragmentStart === -1) {
        query = str.substring(1)
        i = str.length
      } else {
        query = str.substring(1, fragmentStart)
        i = fragmentStart
      }
    }

    str = str.substring(i)

    // Parse fragment: optional, from '#' to end
    if (str.startsWith('#')) {
      fragment = str.substring(1)
    }

    return new URI(scheme, authority, path, query, fragment)
  }

  toString() {
    let result = ''
    if (this.scheme !== null) result += this.scheme + ':'
    if (this.authority !== null) result += '//' + this.authority
    result += this.path
    if (this.query !== null) result += '?' + this.query
    if (this.fragment !== null) result += '#' + this.fragment
    return result
  }
}

// ============================================================================
// Percent Encoding Utilities
// ============================================================================

function isHexDigit(c) {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

function hexToInt(hex) {
  return parseInt(hex, 16)
}

function isUnreserved(c) {
  return (
    (c >= 'A' && c <= 'Z') ||
    (c >= 'a' && c <= 'z') ||
    (c >= '0' && c <= '9') ||
    c === '-' ||
    c === '.' ||
    c === '_' ||
    c === '~'
  )
}

function normalizePercentEncoding(component) {
  if (component === null) return null

  let result = ''
  for (let i = 0; i < component.length; i++) {
    if (component[i] === '%') {
      if (i + 2 >= component.length) {
        return null // Truncated percent-encoding
      }
      const hex1 = component[i + 1]
      const hex2 = component[i + 2]
      if (!isHexDigit(hex1) || !isHexDigit(hex2)) {
        return null // Invalid hex digits
      }
      const charCode = hexToInt(hex1 + hex2)
      const char = String.fromCharCode(charCode)
      if (isUnreserved(char)) {
        result += char
      } else {
        result += '%' + hex1.toUpperCase() + hex2.toUpperCase()
      }
      i += 2
    } else {
      result += component[i]
    }
  }
  return result
}

// ============================================================================
// Authority Parsing
// ============================================================================

function parseAuthority(authority) {
  let userinfo = ''
  let host = authority
  let port = null

  // Find last '@' to separate userinfo and host+port
  const lastAtIdx = authority.lastIndexOf('@')
  if (lastAtIdx !== -1) {
    userinfo = authority.substring(0, lastAtIdx)
    host = authority.substring(lastAtIdx + 1)
  }

  // Find port: everything after first ':' that follows last ']'
  const lastBracketIdx = host.lastIndexOf(']')
  let colonIdx = -1
  if (lastBracketIdx !== -1) {
    colonIdx = host.indexOf(':', lastBracketIdx)
  } else {
    colonIdx = host.indexOf(':')
  }

  if (colonIdx !== -1) {
    port = host.substring(colonIdx + 1)
    host = host.substring(0, colonIdx)
  }

  return { userinfo, host, port }
}

function serializeAuthority(userinfo, host, port) {
  let result = ''
  if (userinfo) result += userinfo + '@'
  result += host
  if (port) result += ':' + port
  return result
}

// ============================================================================
// Normalization
// ============================================================================

function normalizeSchemeLowercase(scheme) {
  if (scheme === null) return null
  let result = ''
  for (let i = 0; i < scheme.length; i++) {
    const c = scheme[i]
    if (c >= 'A' && c <= 'Z') {
      result += String.fromCharCode(c.charCodeAt(0) + 32)
    } else {
      result += c
    }
  }
  return result
}

function normalizeHostLowercase(host) {
  let result = ''
  for (let i = 0; i < host.length; i++) {
    const c = host[i]
    if (c >= 'A' && c <= 'Z') {
      result += String.fromCharCode(c.charCodeAt(0) + 32)
    } else {
      result += c
    }
  }
  return result
}

function removeDotSegments(path) {
  // RFC 3986 section 5.2.4
  let inputBuffer = path
  let outputBuffer = ''

  while (inputBuffer.length > 0) {
    // A: If the input buffer begins with a prefix of "../" or "./"
    if (inputBuffer.startsWith('../')) {
      inputBuffer = inputBuffer.substring(3)
    } else if (inputBuffer.startsWith('./')) {
      inputBuffer = inputBuffer.substring(2)
    }
    // B: If the input buffer begins with a prefix of "/./"
    else if (inputBuffer.startsWith('/./')) {
      inputBuffer = '/' + inputBuffer.substring(3)
    }
    // B: If the input buffer is exactly "/."
    else if (inputBuffer === '/.') {
      inputBuffer = '/'
    }
    // C: If the input buffer begins with a prefix of "/../"
    else if (inputBuffer.startsWith('/../')) {
      inputBuffer = '/' + inputBuffer.substring(4)
      // Remove the last segment from output
      const lastSlashIdx = outputBuffer.lastIndexOf('/')
      if (lastSlashIdx !== -1) {
        outputBuffer = outputBuffer.substring(0, lastSlashIdx)
      }
    }
    // C: If the input buffer is exactly "/.."
    else if (inputBuffer === '/..') {
      inputBuffer = '/'
      // Remove the last segment from output
      const lastSlashIdx = outputBuffer.lastIndexOf('/')
      if (lastSlashIdx !== -1) {
        outputBuffer = outputBuffer.substring(0, lastSlashIdx)
      }
    }
    // D: If the input buffer is exactly "." or ".."
    else if (inputBuffer === '.' || inputBuffer === '..') {
      inputBuffer = ''
    }
    // E: move the first path segment to output
    else {
      let segmentEnd
      if (inputBuffer.startsWith('/')) {
        segmentEnd = inputBuffer.indexOf('/', 1)
        if (segmentEnd === -1) segmentEnd = inputBuffer.length
      } else {
        segmentEnd = inputBuffer.indexOf('/')
        if (segmentEnd === -1) segmentEnd = inputBuffer.length
      }
      outputBuffer += inputBuffer.substring(0, segmentEnd)
      inputBuffer = inputBuffer.substring(segmentEnd)
    }
  }

  return outputBuffer
}

function normalizeURI(uri) {
  const normalized = new URI()

  // 1. Lowercase the scheme
  normalized.scheme = normalizeSchemeLowercase(uri.scheme)

  // 2. Normalize percent-encodings in userinfo (if authority exists)
  let authority = uri.authority
  if (authority !== null) {
    const auth = parseAuthority(authority)

    // Normalize percent-encodings in userinfo
    const normalizedUserinfo = normalizePercentEncoding(auth.userinfo)
    if (normalizedUserinfo === null) {
      return { error: 'userinfo' }
    }

    // Normalize percent-encodings in host
    const normalizedHost = normalizePercentEncoding(auth.host)
    if (normalizedHost === null) {
      return { error: 'host' }
    }

    // 3. Lowercase the host
    const lowercaseHost = normalizeHostLowercase(normalizedHost)

    // 4. Drop default port
    let port = auth.port
    if (port !== null && port !== '') {
      const defaultPorts = {
        'http': '80',
        'https': '443',
        'ws': '80',
        'wss': '443',
        'ftp': '21'
      }
      if (normalized.scheme && defaultPorts[normalized.scheme] === port) {
        port = null
      }
    } else if (port === '') {
      port = null
    }

    normalized.authority = serializeAuthority(normalizedUserinfo, lowercaseHost, port)
  }

  // Normalize percent-encodings in path
  const normalizedPath = normalizePercentEncoding(uri.path)
  if (normalizedPath === null) {
    return { error: 'path' }
  }

  // Remove dot segments from path
  const cleanedPath = removeDotSegments(normalizedPath)

  // If authority is present and path is empty, make it '/'
  if (normalized.authority !== null && cleanedPath === '') {
    normalized.path = '/'
  } else {
    normalized.path = cleanedPath
  }

  // Normalize percent-encodings in query
  const normalizedQuery = normalizePercentEncoding(uri.query)
  if (normalizedQuery === null) {
    return { error: 'query' }
  }
  normalized.query = normalizedQuery

  // Normalize percent-encodings in fragment
  const normalizedFragment = normalizePercentEncoding(uri.fragment)
  if (normalizedFragment === null) {
    return { error: 'fragment' }
  }
  normalized.fragment = normalizedFragment

  return normalized
}

// ============================================================================
// Resolution
// ============================================================================

function resolveURI(base, ref) {
  // RFC 3986 section 5.2.2
  const target = new URI()

  if (ref.scheme !== null) {
    // Reference has a scheme: it's the target
    target.scheme = ref.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else {
    if (ref.authority !== null) {
      // Reference has authority
      target.authority = ref.authority
      target.path = removeDotSegments(ref.path)
      target.query = ref.query
    } else {
      if (ref.path === '') {
        // Reference has empty path
        target.path = base.path
        if (ref.query !== null) {
          target.query = ref.query
        } else {
          target.query = base.query
        }
      } else {
        if (ref.path.startsWith('/')) {
          // Reference path is absolute
          target.path = removeDotSegments(ref.path)
        } else {
          // Merge paths
          if (base.authority !== null && base.path === '') {
            target.path = '/' + ref.path
          } else {
            const lastSlashIdx = base.path.lastIndexOf('/')
            if (lastSlashIdx !== -1) {
              target.path = base.path.substring(0, lastSlashIdx + 1) + ref.path
            } else {
              target.path = ref.path
            }
          }
          target.path = removeDotSegments(target.path)
        }
        target.query = ref.query
      }
      target.authority = base.authority
    }
    target.scheme = base.scheme
  }

  target.fragment = ref.fragment

  return target
}

// ============================================================================
// Main
// ============================================================================

const args = process.argv.slice(2)

if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

const mode = args[0]

// Read stdin
let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch (e) {
  // Handle error reading stdin
}

// Split into lines, dropping empty tail from trailing newline
const lines = input.split('\n')
if (lines.length > 0 && lines[lines.length - 1] === '') {
  lines.pop()
}

let hasError = false

for (let lineNum = 0; lineNum < lines.length; lineNum++) {
  const line = lines[lineNum]
  const recordNum = lineNum + 1

  try {
    if (mode === 'normalize') {
      const uri = URI.parse(line)
      const normalized = normalizeURI(uri)
      if (normalized.error) {
        process.stderr.write(`error: line ${recordNum}: the ${normalized.error} has a truncated percent-encoding\n`)
        process.exit(2)
      }
      console.log(normalized.toString())
    } else {
      // resolve mode
      const spaceIdx = line.indexOf(' ')
      if (spaceIdx === -1) {
        process.stderr.write(`error: line ${recordNum}: expected a base and a reference\n`)
        process.exit(2)
      }

      const baseStr = line.substring(0, spaceIdx)
      const refStr = line.substring(spaceIdx + 1)

      const base = URI.parse(baseStr)
      if (base.scheme === null) {
        process.stderr.write(`error: line ${recordNum}: the base has no scheme\n`)
        process.exit(2)
      }

      const ref = URI.parse(refStr)

      // Check for truncated percent-encodings in reference components
      let refNormError = null
      for (const component of ['scheme', 'authority', 'path', 'query', 'fragment']) {
        if (component === 'scheme' || component === 'authority') {
          // These are checked as part of resolution
          continue
        }
        const result = normalizePercentEncoding(ref[component])
        if (result === null) {
          refNormError = component
          break
        }
      }

      if (refNormError) {
        process.stderr.write(`error: line ${recordNum}: the ${refNormError} has a truncated percent-encoding\n`)
        process.exit(2)
      }

      const resolved = resolveURI(base, ref)
      const normalized = normalizeURI(resolved)
      if (normalized.error) {
        process.stderr.write(`error: line ${recordNum}: the ${normalized.error} has a truncated percent-encoding\n`)
        process.exit(2)
      }
      console.log(normalized.toString())
    }
  } catch (e) {
    process.stderr.write(`error: line ${recordNum}: ${e.message}\n`)
    process.exit(2)
  }
}

process.exit(0)
"}

