{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of mine and theirs over the base they share.
 */

import { readFileSync, writeSync } from 'node:fs'
import { mergeRegions } from './merge.js'

const MODES = ['merge', 'merge2', 'regions']
const SEPARATOR = '%%%'

function fail(message) {
  writeSync(2, `error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

/** The three documents the input holds, as arrays of lines. */
function parseDocuments(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const documents = [[]]
  for (const line of lines) {
    if (line === SEPARATOR) documents.push([])
    else documents[documents.length - 1].push(line)
  }
  return documents
}

function renderMerge(regions, withBase) {
  const out = []
  let conflicted = false
  for (const region of regions) {
    if (region.kind === 'conflict') {
      conflicted = true
      out.push('<<<<<<< mine')
      out.push(...region.mine)
      if (withBase) {
        out.push('||||||| base')
        out.push(...region.base)
      }
      out.push('=======')
      out.push(...region.theirs)
      out.push('>>>>>>> theirs')
    } else {
      out.push(...region.lines)
    }
  }
  return { text: out.map(line => `${line}\n`).join(''), conflicted }
}

function renderRegions(regions) {
  const out = []
  let conflicted = false
  for (const region of regions) {
    if (region.kind === 'conflict') {
      conflicted = true
      out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
    } else {
      out.push(`${region.kind} ${region.lines.length}`)
    }
  }
  return { text: out.map(line => `${line}\n`).join(''), conflicted }
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || !MODES.includes(mode)) fail('usage: cli.js merge|merge2|regions')

  const documents = parseDocuments(readStdin())
  if (documents.length !== 3) fail('expected three parts separated by %%%')

  const [mine, base, theirs] = documents
  const regions = mergeRegions(mine, base, theirs)
  const { text, conflicted } = mode === 'regions' ? renderRegions(regions) : renderMerge(regions, mode === 'merge')

  if (text.length > 0) writeSync(1, text)
  process.exit(conflicted ? 1 : 0)
}

main(process.argv.slice(2))
"}

