  ['d', { cost: 1, dependencies: new Set(['b', 'c']) }]
]);

const finished = new Map();
const workerFree = [0, 0];
let iterations = 0;
let maxIter = 20;

const isReady = (name, atTime) => {
  const deps = tasks.get(name).dependencies;
  for (const dep of deps) {
    if (!finished.has(dep) || finished.get(dep) > atTime) {
      return false;
    }
  }
  return true;
};

let remaining = new Set(['a', 'b', 'c', 'd']);
let currentTime = 0;

while (remaining.size > 0 && iterations < maxIter) {
  iterations++;
  currentTime = Math.min(...workerFree);
  console.log(`\nIteration ${iterations}:`);
  console.log(`  currentTime=${currentTime}, workerFree=[${workerFree}], remaining=[${Array.from(remaining)}]`);

  let anyTaskAssigned = false;
  let taskAssigned = true;

  while (taskAssigned) {
    taskAssigned = false;

    let freeWorker = -1;
    for (let w = 0; w < 2; w++) {
      if (workerFree[w] <= currentTime) {
        freeWorker = w;
        break;
      }
    }

    console.log(`    freeWorker=${freeWorker}`);

    if (freeWorker === -1) break;

    let bestTask = null;
    for (const task of remaining) {
      console.log(`      task=${task}, isReady=${isReady(task, currentTime)}`);
      if (isReady(task, currentTime)) {
        bestTask = task;
        break;
      }
    }

    console.log(`    bestTask=${bestTask}`);

    if (bestTask) {
      const cost = tasks.get(bestTask).cost;
      const start = currentTime;
      const finish = start + cost;
      workerFree[freeWorker] = finish;
      finished.set(bestTask, finish);
      remaining.delete(bestTask);
      taskAssigned = true;
      anyTaskAssigned = true;
      console.log(`    ASSIGNED ${bestTask} to worker ${freeWorker} (${start}-${finish})`);
    } else {
      break;
    }
  }

  console.log(`  anyTaskAssigned=${anyTaskAssigned}`);

  if (!anyTaskAssigned && remaining.size > 0) {
    let nextTime = Infinity;
    for (const t of workerFree) {
      if (t > currentTime) {
        nextTime = Math.min(nextTime, t);
      }
    }
    console.log(`  nextTime=${nextTime}, currentTime=${currentTime}`);
    if (nextTime === Infinity) {
      console.log(`  Breaking - no worker will become free`);
      break;
    }
    currentTime = nextTime;
