test('pack onto two workers reaches the unlimited makespan of the diamond', () => {
  assert.equal(run(['pack', '2'], DIAMOND).out, 'worker 0: a@0-3 c@3-7 d@7-8\nworker 1: b@3-5\nmakespan 8\n')
