{"file_path":"src/graph.js","content":"import { cycleError } from './errors.js'

// A build graph: tasks with costs and dependency edges.
export class Graph {
  constructor() {
    this.costs = new Map() // name -> cost
    this.deps = new Map() // name -> Set of dependencies
    this.dependents = new Map() // name -> Set of tasks depending on it
  }

  addTask(name, cost) {
    this.costs.set(name, cost)
    this.deps.set(name, new Set())
    this.dependents.set(name, new Set())
  }

  addEdge(from, to) {
    this.deps.get(from).add(to)
    this.dependents.get(to).add(from)
  }

  // Task names in ascending order.
  names() {
    return [...this.costs.keys()].sort()
  }

  sortedDeps(name) {
    return [...this.deps.get(name)].sort()
  }

  // The first cycle a depth-first search finds, or null. Iterative, so that
  // very deep graphs cannot overflow the call stack.
  findCycle() {
    const OPEN = 1
    const DONE = 2
    const state = new Map()

    for (const root of this.names()) {
      if (state.get(root) === DONE) continue
      const path = [root]
      const frames = [{ name: root, deps: this.sortedDeps(root), at: 0 }]
      state.set(root, OPEN)

      while (frames.length > 0) {
        const frame = frames[frames.length - 1]
        if (frame.at < frame.deps.length) {
          const next = frame.deps[frame.at++]
          const seen = state.get(next)
          if (seen === OPEN) {
            const start = path.indexOf(next)
            return [...path.slice(start), next]
          }
          if (seen === DONE) continue
          state.set(next, OPEN)
          path.push(next)
          frames.push({ name: next, deps: this.sortedDeps(next), at: 0 })
        } else {
          state.set(frame.name, DONE)
          path.pop()
          frames.pop()
        }
      }
    }
    return null
  }

  assertAcyclic() {
    const cycle = this.findCycle()
    if (cycle) throw cycleError(cycle)
  }

  // Earliest start, finish and wave depth of every task, assuming unlimited
  // workers. Computed in topological order.
  schedule() {
    const depth = new Map()
    const start = new Map()
    const finish = new Map()
    const pending = new Map()
    const queue = []

    for (const name of this.names()) {
      const count = this.deps.get(name).size
      pending.set(name, count)
      depth.set(name, 0)
      start.set(name, 0)
      if (count === 0) queue.push(name)
    }

    for (let head = 0; head < queue.length; head++) {
      const name = queue[head]
      finish.set(name, start.get(name) + this.costs.get(name))
      for (const next of this.dependents.get(name)) {
        if (depth.get(next) < depth.get(name) + 1) depth.set(next, depth.get(name) + 1)
        if (start.get(next) < finish.get(name)) start.set(next, finish.get(name))
        const left = pending.get(next) - 1
        pending.set(next, left)
        if (left === 0) queue.push(next)
      }
    }

    let total = 0
    for (const value of finish.values()) if (value > total) total = value
    return { depth, start, finish, total }
  }

  // Priority: the cost of the longest chain beginning at the task, counting
  // its own cost and the costs of the tasks that follow it.
  priorities() {
    const priority = new Map()
    const after = new Map() // longest chain strictly after the task
    const pending = new Map()
    const queue = []

    for (const name of this.names()) {
      const count = this.dependents.get(name).size
      pending.set(name, count)
      after.set(name, 0)
      if (count === 0) queue.push(name)
    }

    for (let head = 0; head < queue.length; head++) {
      const name = queue[head]
      priority.set(name, this.costs.get(name) + after.get(name))
      for (const dep of this.deps.get(name)) {
        if (after.get(dep) < priority.get(name)) after.set(dep, priority.get(name))
        const left = pending.get(dep) - 1
        pending.set(dep, left)
        if (left === 0) queue.push(dep)
      }
    }
    return priority
  }
}
"}

