{"file_path":"src/cli.js","content":"#!/usr/bin/env node
// Reads a build graph on standard input and reports waves, timings or a
// worker-packed schedule.
import { Failure, fail, usageError } from './errors.js'
import { parseGraph } from './parse.js'
import * as commands from './commands.js'

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { command: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    const workers = argv[1]
    if (!/^[1-9][0-9]*$/.test(workers)) throw fail('error: workers must be a positive integer')
    return { command: 'pack', workers: Number(workers) }
  }
  throw usageError()
}

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const { command, workers } = parseArgs(process.argv.slice(2))
  const graph = parseGraph(await readStdin())
  graph.assertAcyclic()
  const output =
    command === 'waves'
      ? commands.waves(graph)
      : command === 'explain'
        ? commands.explain(graph)
        : commands.pack(graph, workers)
  process.stdout.write(output)
}

main().catch((error) => {
  if (error instanceof Failure) {
    process.stderr.write(error.message + '\n')
    process.exitCode = error.code
  } else {
    process.stderr.write(`error: ${error && error.message ? error.message : error}\n`)
    process.exitCode = 1
  }
})
"}

