{"file_path":"src/heap.js","content":"// A minimal binary heap; `before(a, b)` is true when a comes out first.
export class Heap {
  constructor(before) {
    this.before = before
    this.items = []
  }

  get size() {
    return this.items.length
  }

  peek() {
    return this.items[0]
  }

  push(item) {
    const items = this.items
    items.push(item)
    let i = items.length - 1
    while (i > 0) {
      const parent = (i - 1) >> 1
      if (!this.before(items[i], items[parent])) break
      ;[items[i], items[parent]] = [items[parent], items[i]]
      i = parent
    }
  }

  pop() {
    const items = this.items
    const top = items[0]
    const last = items.pop()
    if (items.length > 0) {
      items[0] = last
      let i = 0
      for (;;) {
        const left = 2 * i + 1
        const right = left + 1
        let best = i
        if (left < items.length && this.before(items[left], items[best])) best = left
        if (right < items.length && this.before(items[right], items[best])) best = right
        if (best === i) break
        ;[items[i], items[best]] = [items[best], items[i]]
        i = best
      }
    }
    return top
  }
}
"}

