import { readFileSync } from 'fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

class Scanner {
  constructor(source) {
    this.source = source
    this.position = 0
    this.line = 1
    this.column = 1
    this.tokens = []
    this.errors = []
  }

  peek(offset = 0) {
    return this.source[this.position + offset]
  }

  advance() {
    const ch = this.source[this.position]
    this.position++
