        this.currentToken = this.tokenizer.nextToken()

        // Built-in functions
        if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'].includes(name)) {
          return { type: 'FUNCTION_CALL', name, args }
        } else {
          return { type: 'FUNCTION_CALL', name, args, isUnknown: true }
        }
      } else {
        // It's a cell address
        return { type: 'CELL_ADDR', value: name }
      }
    }

    return '#ERR!'
  }

  parseArgument() {
    const expr = this.parseFormula()

    // Check for range
    if (this.currentToken === ':') {
      this.currentToken = this.tokenizer.nextToken()
      const end = this.parseFormula()
      return { type: 'RANGE', start: expr, end }
    }

    return expr
  }
}

function isValidAddress(address) {
  const match = address.match(/^([A-Z]{1,2})(\d{1,3})$/)
  if (!match) return false

  const row = parseInt(match[2], 10)
  if (row < 1) return false

  const col = match[1]
  if (col.length === 1) return true
  if (col < 'AA' || col > 'ZZ') return false

  return true
}

function addressToCoords(address) {
  const match = address.match(/^([A-Z]{1,2})(\d{1,3})$/)
  const col = match[1]
  const row = parseInt(match[2], 10)

  let colNum
  if (col.length === 1) {
    colNum = col.charCodeAt(0) - 'A'.charCodeAt(0)
  } else {
    colNum = 26 + (col.charCodeAt(0) - 'A'.charCodeAt(0)) * 26 + (col.charCodeAt(1) - 'A'.charCodeAt(0))
  }

  return { col: colNum, row }
}

function coordsToAddress(col, row) {
  let address = ''
  if (col < 26) {
    address = String.fromCharCode('A'.charCodeAt(0) + col)
  } else {
    col -= 26
    address = String.fromCharCode('A'.charCodeAt(0) + Math.floor(col / 26)) + 
              String.fromCharCode('A'.charCodeAt(0) + (col % 26))
  }
  address += row
  return address
}

function parseContent(content) {
  if (content === '') return 0
  if (ERROR_TOKENS.has(content)) return content

  if (content.startsWith('=')) {
    return { type: 'FORMULA', formula: content.substring(1) }
  }

  // Try to parse as number
  const numMatch = content.match(/^-?\d+(\.\d+)?$/)
  if (numMatch) return parseFloat(content)

  return content
}

export function createEvaluator(cells) {
  const evaluated = new Map()
  const evaluating = new Set()

  function evaluate(address) {
    // Check for cycle
    if (evaluating.has(address)) {
      return '#CYCLE!'
    }

    // Already evaluated
    if (evaluated.has(address)) {
      return evaluated.get(address)
    }

    // Cell doesn't exist
    if (!cells.has(address)) {
      return 0
    }

    const cell = cells.get(address)
    evaluating.add(address)

    const parsed = parseContent(cell.content)
    let result

    if (parsed && typeof parsed === 'object' && parsed.type === 'FORMULA') {
      // Parse and evaluate formula
      try {
        const parser = new Parser(parsed.formula)
        const ast = parser.parseFormula()
        result = evaluateAst(ast)
      } catch (e) {
        result = '#ERR!'
      }
    } else {
      result = parsed
    }

    evaluating.delete(address)
    evaluated.set(address, result)
    return result
  }

  function evaluateAst(ast) {
    if (typeof ast === 'string') return ast
    if (typeof ast === 'number') return ast
    if (typeof ast === 'boolean') return ast

    if (!ast || typeof ast !== 'object') return '#ERR!'

    if (ast.type === 'LITERAL') return ast.value

    if (ast.type === 'CELL_ADDR') {
      if (!isValidAddress(ast.value)) return '#REF!'
      return evaluate(ast.value)
    }

    if (ast.type === 'BINARY_OP') {
      const left = evaluateAst(ast.left)
      if (isError(left)) return left

      const right = evaluateAst(ast.right)
      if (isError(right)) return right

      switch (ast.op) {
        case '+': {
          const ln = toNumber(left)
          if (isError(ln)) return ln
          const rn = toNumber(right)
          if (isError(rn)) return rn
          const result = ln + rn
          if (!isFinite(result)) return '#DIV/0!'
          return result
        }
        case '-': {
          const ln = toNumber(left)
          if (isError(ln)) return ln
          const rn = toNumber(right)
          if (isError(rn)) return rn
          const result = ln - rn
          if (!isFinite(result)) return '#DIV/0!'
          return result
        }
        case '*': {
          const ln = toNumber(left)
          if (isError(ln)) return ln
          const rn = toNumber(right)
          if (isError(rn)) return rn
          const result = ln * rn
          if (!isFinite(result)) return '#DIV/0!'
          return result
        }
        case '/': {
          const ln = toNumber(left)
          if (isError(ln)) return ln
          const rn = toNumber(right)
          if (isError(rn)) return rn
          if (rn === 0) return '#DIV/0!'
          const result = ln / rn
          if (!isFinite(result)) return '#DIV/0!'
          return result
        }
        case '^': {
          const ln = toNumber(left)
          if (isError(ln)) return ln
          const rn = toNumber(right)
          if (isError(rn)) return rn
          const result = Math.pow(ln, rn)
          if (!isFinite(result)) return '#DIV/0!'
          return result
        }
        case '=':
          return compareValues(left, right) === 0
        case '<>':
          return compareValues(left, right) !== 0
        case '<':
          return compareValues(left, right) < 0
        case '<=':
          return compareValues(left, right) <= 0
        case '>':
          return compareValues(left, right) > 0
        case '>=':
          return compareValues(left, right) >= 0
      }
    }

    if (ast.type === 'UNARY_OP') {
      const expr = evaluateAst(ast.expr)
      if (isError(expr)) return expr

      const num = toNumber(expr)
      if (isError(num)) return num

      if (ast.op === '-') return -num
      if (ast.op === '+') return num
    }

    if (ast.type === 'FUNCTION_CALL') {
      if (ast.isUnknown) return '#NAME?'

      const values = []
      for (const arg of ast.args) {
        if (arg.type === 'RANGE') {
          const rangeValues = evaluateRange(arg)
          if (isError(rangeValues)) return rangeValues
          values.push(...rangeValues)
        } else {
          const val = evaluateAst(arg)
          if (isError(val)) return val
          values.push(val)
        }
      }

      return executeFunction(ast.name, values)
    }

    return '#ERR!'
  }

  function evaluateRange(range) {
    const start = evaluateAst(range.start)
    if (isError(start)) return start

    if (!(range.start.type === 'CELL_ADDR' && isValidAddress(range.start.value))) {
      return '#REF!'
    }

    const end = evaluateAst(range.end)
    if (isError(end)) return end

    if (!(range.end.type === 'CELL_ADDR' && isValidAddress(range.end.value))) {
      return '#REF!'
    }

    const startAddr = range.start.value
    const endAddr = range.end.value

    const startCoords = addressToCoords(startAddr)
    const endCoords = addressToCoords(endAddr)

    const minCol = Math.min(startCoords.col, endCoords.col)
    const maxCol = Math.max(startCoords.col, endCoords.col)
    const minRow = Math.min(startCoords.row, endCoords.row)
    const maxRow = Math.max(startCoords.row, endCoords.row)

    const values = []
    for (let col = minCol; col <= maxCol; col++) {
      for (let row = minRow; row <= maxRow; row++) {
        const addr = coordsToAddress(col, row)
        values.push(evaluate(addr))
      }
    }

    return values
  }

  function executeFunction(name, values) {
    switch (name) {
      case 'SUM': {
        if (values.length === 0) return 0
        let sum = 0
        for (const val of values) {
          const num = toNumber(val)
          if (isError(num)) return num
          sum += num
        }
        return sum
      }
      case 'MIN': {
        if (values.length === 0) return 0
        let min = Infinity
        for (const val of values) {
          const num = toNumber(val)
          if (isError(num)) return num
          min = Math.min(min, num)
        }
        return min === Infinity ? 0 : min
      }
      case 'MAX': {
        if (values.length === 0) return 0
        let max = -Infinity
        for (const val of values) {
          const num = toNumber(val)
          if (isError(num)) return num
          max = Math.max(max, num)
        }
        return max === -Infinity ? 0 : max
      }
      case 'COUNT': {
        let count = 0
        for (const val of values) {
          if (isNumber(val)) count++
        }
        return count
      }
      case 'AVG': {
        if (values.length === 0) return 0
        let sum = 0
        let count = 0
        for (const val of values) {
          const num = toNumber(val)
          if (isError(num)) return num
          sum += num
          count++
        }
        if (count === 0) return 0
        return sum / count
      }
      case 'ABS': {
        if (values.length !== 1) return '#ERR!'
        const num = toNumber(values[0])
        if (isError(num)) return num
        return Math.abs(num)
      }
      case 'IF': {
        if (values.length !== 3) return '#ERR!'
        const cond = values[0]
        const isTruthy = (isBoolean(cond) && cond) || (isNumber(cond) && cond !== 0)
        return isTruthy ? values[1] : values[2]
      }
    }
    return '#ERR!'
  }

  function getDepsForAst(ast) {
    if (typeof ast !== 'object' || !ast) return []

    const deps = []

    if (ast.type === 'CELL_ADDR') {
      if (isValidAddress(ast.value)) {
        deps.push(ast.value)
      }
    } else if (ast.type === 'BINARY_OP') {
      deps.push(...getDepsForAst(ast.left))
      deps.push(...getDepsForAst(ast.right))
    } else if (ast.type === 'UNARY_OP') {
      deps.push(...getDepsForAst(ast.expr))
    } else if (ast.type === 'FUNCTION_CALL') {
      for (const arg of ast.args) {
        if (arg.type === 'RANGE') {
          // Expand range
          if (arg.start.type === 'CELL_ADDR' && isValidAddress(arg.start.value) &&
              arg.end.type === 'CELL_ADDR' && isValidAddress(arg.end.value)) {
            const startCoords = addressToCoords(arg.start.value)
            const endCoords = addressToCoords(arg.end.value)

            const minCol = Math.min(startCoords.col, endCoords.col)
            const maxCol = Math.max(startCoords.col, endCoords.col)
            const minRow = Math.min(startCoords.row, endCoords.row)
            const maxRow = Math.max(startCoords.row, endCoords.row)

            for (let col = minCol; col <= maxCol; col++) {
              for (let row = minRow; row <= maxRow; row++) {
                deps.push(coordsToAddress(col, row))
              }
            }
          }
        } else {
          deps.push(...getDepsForAst(arg))
        }
      }
    }

    return deps
  }

  function getDependencies() {
    const result = new Map()

    for (const [address, cell] of cells) {
      const parsed = parseContent(cell.content)
      if (parsed && typeof parsed === 'object' && parsed.type === 'FORMULA') {
        try {
          const parser = new Parser(parsed.formula)
          const ast = parser.parseFormula()
          const deps = getDepsForAst(ast)
          // Remove duplicates and sort
          const uniqueDeps = [...new Set(deps)]
          uniqueDeps.sort((a, b) => {
            const coordsA = addressToCoords(a)
            const coordsB = addressToCoords(b)
            if (coordsA.col !== coordsB.col) return coordsA.col - coordsB.col
            return coordsA.row - coordsB.row
          })
          result.set(address, uniqueDeps)
        } catch (e) {
          result.set(address, [])
        }
      } else {
        result.set(address, [])
      }
    }

    return result
  }

  return {
    evaluate,
    evaluateAll() {
      for (const address of cells.keys()) {
        evaluate(address)
      }
      return evaluated
    },
    getDependencies
  }
}
"}

