 * Output formatting for values and deps modes
 */

function addressToCoords(address) {
  const match = address.match(/^([A-Z]{1,2})(\d{1,3})$/)
  const col = match[1]
  const row = parseInt(match[2], 10)

  let colNum
  if (col.length === 1) {
    colNum = col.charCodeAt(0) - 'A'.charCodeAt(0)
  } else {
    colNum = 26 + (col.charCodeAt(0) - 'A'.charCodeAt(0)) * 26 + (col.charCodeAt(1) - 'A'.charCodeAt(0))
  }

  return { col: colNum, row }
}

function formatNumber(num) {
  // Round to 10 significant digits
  const str = num.toPrecision(10)
  // Remove trailing zeros after decimal point
  let result = parseFloat(str).toString()
  // But we need to follow JavaScript's behavior
  if (str.includes('e')) {
    result = parseFloat(str).toString()
  } else {
    result = parseFloat(str).toString()
  }
  return result
}

function formatValue(value) {
  if (typeof value === 'number') {
    return formatNumber(value)
  } else if (typeof value === 'boolean') {
    return value ? 'TRUE' : 'FALSE'
  } else if (typeof value === 'string') {
    return value
  }
  return String(value)
}

export const formatOutput = {
  values(evaluated) {
    const lines = []

    // Sort by column, then by row
    const addresses = Array.from(evaluated.keys())
    addresses.sort((a, b) => {
      const coordsA = addressToCoords(a)
      const coordsB = addressToCoords(b)
      if (coordsA.col !== coordsB.col) return coordsA.col - coordsB.col
      return coordsA.row - coordsB.row
    })

    for (const address of addresses) {
      const value = evaluated.get(address)
      lines.push(`${address}=${formatValue(value)}`)
    }

    return lines.join('\n') + '\n'
  },

  deps(dependencies) {
    const lines = []

    // Sort by column, then by row
    const addresses = Array.from(dependencies.keys())
    addresses.sort((a, b) => {
      const coordsA = addressToCoords(a)
      const coordsB = addressToCoords(b)
      if (coordsA.col !== coordsB.col) return coordsA.col - coordsB.col
      return coordsA.row - coordsB.row
    })

    for (const address of addresses) {
      const deps = dependencies.get(address)
      if (deps.length === 0) {
        lines.push(`${address}:`)
      } else {
        lines.push(`${address}: ${deps.join(' ')}`)
      }
    }

    return lines.join('\n') + '\n'
  }
}
"}

