import { getDependencies } from './evaluator.js'

function parseAddress(addr) {
  const match = addr.match(/^([A-Za-z]{1,2})(\d{1,3})$/)
  if (!match) return null

  const col = match[1].toUpperCase()
  const row = parseInt(match[2], 10)

  return { col, row }
}

function compareAddresses(a1, a2) {
  const p1 = parseAddress(a1)
  const p2 = parseAddress(a2)
  if (!p1 || !p2) return 0

  const col1 = colToNum(p1.col)
  const col2 = colToNum(p2.col)

  if (col1 !== col2) return col1 - col2
  return p1.row - p2.row
}

function colToNum(col) {
  if (col.length === 1) {
    return col.charCodeAt(0) - 'A'.charCodeAt(0)
  } else {
    return 26 + (col.charCodeAt(1) - 'A'.charCodeAt(0))
  }
}

function formatValue(value) {
  if (value.type === 'error') {
    return value.val
  }
  if (value.type === 'boolean') {
    return value.val ? 'TRUE' : 'FALSE'
  }
  if (value.type === 'number') {
    // Round to 10 significant digits
    const str = value.val.toPrecision(10)
    // Remove trailing zeros after decimal point, but keep integers as is
    return parseFloat(str).toString()
  }
  if (value.type === 'text') {
    return value.val
  }
  return ''
}

export function formatOutput(sheet, mode) {
  const addresses = Array.from(sheet.keys()).sort(compareAddresses)

  if (mode === 'values') {
    return addresses
      .map(addr => `${addr}=${formatValue(sheet.get(addr))}`)
      .join('\n') + (addresses.length > 0 ? '\n' : '')
  }

  if (mode === 'deps') {
    // Re-parse to get dependencies
    const cells = new Map()
    for (const [addr, value] of sheet) {
      // We need the original cell content, which we don't have here
      // We need to reconstruct it from the cells passed to evaluateSheet
      // Actually, we need to pass the cells through to formatOutput
      // Let me refactor
    }
    return ''
  }
}

export function formatOutputWithCells(sheet, cells, mode) {
  const addresses = Array.from(sheet.keys()).sort(compareAddresses)

  if (mode === 'values') {
    return addresses
      .map(addr => `${addr}=${formatValue(sheet.get(addr))}`)
      .join('\n') + (addresses.length > 0 ? '\n' : '')
  }

  if (mode === 'deps') {
    const deps = getDependencies(cells)
    return addresses
      .map(addr => {
        const depSet = deps.get(addr) || new Set()
        const depList = Array.from(depSet).sort(compareAddresses)
        return `${addr}: ${depList.length > 0 ? depList.join(' ') : ''}`
      })
      .join('\n') + (addresses.length > 0 ? '\n' : '')
  }
}
"}

