{"file_path":"src/formatter.js","content":"/**
 * Printing a sheet, in either mode.
 */

import { compareAddresses } from './parser.js'
import { evaluateSheet, sheetDependencies } from './evaluator.js'

/** A number as JavaScript prints it once rounded to ten significant digits. */
export function formatNumber(value) {
  const rounded = Number(value.toPrecision(10))
  return String(rounded === 0 ? 0 : rounded)
}

export function formatValue(value) {
  switch (value.kind) {
    case 'number':
      return formatNumber(value.value)
    case 'boolean':
      return value.value ? 'TRUE' : 'FALSE'
    case 'error':
      return value.value
    default:
      return value.value
  }
}

function ordered(cells) {
  return Array.from(cells.keys()).sort(compareAddresses)
}

export function formatValues(cells) {
  const values = evaluateSheet(cells)
  return ordered(cells)
    .map(address => `${address}=${formatValue(values.get(address))}\n`)
    .join('')
}

export function formatDeps(cells) {
  const dependencies = sheetDependencies(cells)
  return ordered(cells)
    .map(address => {
      const named = Array.from(dependencies.get(address)).sort(compareAddresses)
      return `${address}:${named.map(dep => ` ${dep}`).join('')}\n`
    })
    .join('')
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every declared cell
 * of the sheet read from standard input, and `node src/cli.js deps` prints the
 * cells each one names.
 */

import { parseInput } from './parser.js'
import { formatValues, formatDeps } from './formatter.js'

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exitCode = 2
}

const args = process.argv.slice(2)
const mode = args.length === 1 ? args[0] : null

if (mode !== 'values' && mode !== 'deps') {
  fail('error: usage: cli.js values|deps')
} else {
  let input = ''
  process.stdin.setEncoding('utf8')
  process.stdin.on('data', chunk => {
    input += chunk
  })
  process.stdin.on('end', () => {
    try {
      const cells = parseInput(input)
      process.stdout.write(mode === 'values' ? formatValues(cells) : formatDeps(cells))
      process.exitCode = 0
    } catch (error) {
      fail(error.message)
    }
  })
}
"}

